-- Sources d'information du secteur « santé » du département 86 (Vienne).
-- 20 sources, 61 URL distinctes, toutes en HTTP 200 le 2026-11-22 (curl -L, User-Agent navigateur, délai 20 s).
-- Corpus : bench/corpus/sources-sante-86.jsonl — preuve : bench/results/verification-sources-sante-86.json

BEGIN;

CREATE TABLE IF NOT EXISTS source_verification (
  id                bigserial PRIMARY KEY,
  source_id         text        NOT NULL REFERENCES source(id) ON DELETE CASCADE,
  url               text        NOT NULL,
  code_http         integer,
  content_type      text,
  items             integer     NOT NULL DEFAULT 0 CHECK (items >= 0),
  derniere_item_at  timestamptz,
  ms                integer     NOT NULL CHECK (ms >= 0),
  verifie_at        timestamptz NOT NULL DEFAULT now(),
  user_agent        text        NOT NULL,
  etat              text        NOT NULL CHECK (etat IN ('ok200', 'muette', 'morte', 'lente')),
  motif             text
);

CREATE INDEX IF NOT EXISTS idx_source_verification_source_date
  ON source_verification (source_id, verifie_at DESC, id DESC);
CREATE INDEX IF NOT EXISTS idx_source_verification_verifie_at
  ON source_verification (verifie_at DESC);

ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  url = EXCLUDED.url,
  parser = EXCLUDED.parser,
  description = EXCLUDED.description,
  region = EXCLUDED.region,
  department = EXCLUDED.department;

CREATE TEMP TABLE verif_sante86 (source_id text, urls text[]) ON COMMIT DROP;

SELECT v.source_id, a.url, 200, NULL, 0, 0, now(), 'RadarCyberCorpus/1.0', 'ok200',
       'Corpus santé-86 : HTTP 200 vérifié le 2026-11-22'
FROM verif_sante86 v
CROSS JOIN LATERAL unnest(v.urls) AS a(url);

COMMIT;
